#!/usr/bin/env python3
# luxarch:release-actions hook v1 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""What a release action is, for the hooks that record and consume one.

A release action is a step or a heads-up an issue's work needs when it ships. It is recorded as
the issue closes, on the issue (the `release-action` label and a `Release: <the step>` line in its
close summary) and in the repo (`release-actions/<KEY>.md`, committed with the work). The release
that holds the work consumes the file (`--doc FLEET-RELEASE-PROCESS` §3a).
"""

from __future__ import annotations

import re

RELEASE_ACTION_LABEL = "release-action"
ACTIONS_DIR = "release-actions"
_KEY = re.compile(r"[A-Z][A-Z0-9]{0,15}-\d+")
_RELEASE_LINE = re.compile(
    r"^[ \t>]*(?:[-*+][ \t]+|\d+[.)][ \t]+)?[*_]{0,2}release(?:[ \t]+actions?)?[*_]{0,2}"
    r"[ \t]*:[*_]{0,2}[ \t]*(?P<step>\S.*)$",
    re.IGNORECASE | re.MULTILINE,
)
# A `Release:` line that says the release needs nothing, or where the work shipped, names no step:
# `none`, `none needed`, `nothing to do`, `no action`, `n/a`, `-`, a version alone or with what
# shipped there (`0.361.0`, `shipped in v0.370.0`, `0.370.0 (f3cf6cca), image pushed`).
_VERSION = r"v?\d+(?:\.\d+)+[0-9A-Za-z.+-]*"
_NO_STEP = re.compile(
    r"[*_`]*(?:(?:none|nothing|no[ \t]+(?:release[ \t]+)?actions?|n/?a)\b.*|-+"
    rf"|(?:shipped|released)\b.*|{_VERSION}[*_`.]*|{_VERSION}[ \t]*\([0-9a-f]{{7,40}}\).*)",
    re.IGNORECASE,
)


def release_steps(summary: object) -> list[str]:
    """The steps a close summary's `Release:` lines name, in order; a line that says the release
    needs nothing, or only where the work shipped, names none."""
    if not isinstance(summary, str):
        return []
    return [
        m.group("step").strip()
        for m in _RELEASE_LINE.finditer(summary)
        if not _NO_STEP.fullmatch(m.group("step").strip())
    ]


def action_key(path: str) -> str:
    """The issue key of `release-actions/<KEY>.md`, or '' for any other path."""
    head, _, name = path.strip().rpartition("/")
    if head != ACTIONS_DIR or not name.endswith(".md"):
        return ""
    key = name[: -len(".md")]
    return key if _KEY.fullmatch(key) else ""


def action_path(key: str) -> str:
    return f"{ACTIONS_DIR}/{key}.md"
